      "resource": "ServiceRequest",
      "operation": "createResource",
      "tip": "Always provide a top-level 'body_json' property containing the FHIR resource. For example:
{
  body_json: {
    resourceType: 'ServiceRequest',
    status: 'active',
    intent: 'plan',
    category: [{ coding: [{ system: 'http://terminology.hl7.org/CodeSystem/service-category', code: 'surgical' }] }],
    subject: { reference: 'Patient/PAT002' },
    occurrenceDateTime: '2025-05-15T00:00:00Z'
  }
}",
    }
